body.command:
mkdir -p .claude-plugin hooks commands && node -e "
const fs = require('fs');
const events = ['SessionStart','UserPromptSubmit','PreToolUse','PostToolUse','PostToolUseFailure','PermissionRequest','Notification','SubagentStart','SubagentStop','PreCompact','Stop','StopFailure','SessionEnd'];
const hook = { type: 'command', command: 'node \"\${CLAUDE_PLUGIN_ROOT}/bridge/hook.js\"', async: true, timeout: 5 };
fs.writeFileSync('hooks/hooks.json', JSON.stringify({ description: 'Streams Claude Code activity to the dotpals bridge so a pal animates live.', hooks: Object.fromEntries(events.map(e => [e, [{ hooks: [hook] }]])) }, null, 2) + '\n');
fs.writeFileSync('.claude-plugin/plugin.json', JSON.stringify({
  name: 'dotpals',
  version: '0.1.0',
  description: 'A fluffy animated pal that reacts live to Claude Code: thinking, running tools, asking permission, and celebrating when done.',
  author: { name: 'dotpals contributors' },
  license: 'MIT',
  keywords: ['animation', 'mascot', 'status', 'hooks']
}, null, 2) + '\n');
fs.writeFileSync('.claude-plugin/marketplace.json', JSON.stringify({
  name: 'dotpals',
  owner: { name: 'dotpals contributors' },
  plugins: [{ name: 'dotpals', source: './', description: 'Animated pals that react live to Claude Code.' }]
}, null, 2) + '\n');
"
cat hooks/hooks.json | head -12

node -e "
const fs=require('fs'); const p='.claude-plugin/marketplace.json'; const m=JSON.parse(fs.readFileSync(p));
fs.writeFileSync(p, JSON.stringify({ name: m.name, owner: m.owner, description: 'Fluffy animated pals that react live to your Claude Code sessions.', plugins: m.plugins }, null, 2) + '\n');" && claude plugin validate .claude-plugin/marketplace.json --strict 2>&1 | tail -3; claude plugin validate .claude-plugin/plugin.json --strict 2>&1 | tail -4; claude plugin validate commands --strict 2>&1 | tail -4
